if($path==='robots.txt'){ header('Content-Type: text/plain; charset=utf-8'); $host=($_SERVER['HTTPS']??'')==='on'?'https':'http'; echo "User-agent: *\nAllow: /\nDisallow: /admin\nDisallow: /login\nSitemap: {$host}{$_SERVER['HTTP_HOST']}".url('sitemap.xml')."\n"; exit; }
if($path==='sitemap.xml'){ header('Content-Type: application/xml; charset=utf-8'); echo '<?xml version="1.0" encoding="UTF-8"?>'."\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n"; $urls=[['loc'=>url(),'lastmod'=>now()]]; foreach(db()->query('SELECT slug,updated_at,language,type FROM content WHERE status="published" ORDER BY id') as $r){ $p=$r['type']==='page'?url($r['slug']):url($r['type'].'/'.$r['slug']); $urls[]=['loc'=>$p,'lastmod'=>substr((string)$r['updated_at'],0,10)]; } foreach(array_unique(array_map(fn($u)=>$u['loc'],$urls)) as $u){ $lu=array_values(array_filter($urls,fn($x)=>$x['loc']===$u))[0]; echo "  <url><loc>".e($lu['loc'])."</loc><lastmod>".e($lu['lastmod'])."</lastmod></url>\n"; } echo "</urlset>"; exit; }

